package com.biocircular.monitoring; import org.springframework.beans.factory.annotation.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.*; import java.util.*;
@RestController @RequestMapping("/api/monitoring") public class MonitoringController{final RestTemplate http=new RestTemplate();@Value("${AUTH_SERVICE_URL:http://auth-service:8080}")String auth;@Value("${GESTION_SERVICE_URL:http://gestion-service:8080}")String gestion;@Value("${COMPOSTAJE_SERVICE_URL:http://compostaje-service:8080}")String compost;@Value("${REPORTES_SERVICE_URL:http://reportes-service:8080}")String reportes;@GetMapping("/servicios")Map<String,Object> all(){return Map.of("auth",health(auth),"gestion",health(gestion),"compostaje",health(compost),"reportes",health(reportes));}Object health(String url){try{return http.getForObject(url+"/actuator/health",Object.class);}catch(Exception e){return Map.of("status","DOWN");}}}
